import re

def check_if_last_char_is_a_letter(txt):
    if not txt.strip():
        return False

    last_char = txt[-1]
    if not last_char.isalpha():
        return False

    # Check if the last character is part of a word (not a punctuation/whitespace)
    if re.search(rf'[^a-zA-Z\s]{last_char}', txt):
        return False

    return True
